let center = NotificationCenter.default        // process-wide hub
extension Notification.Name { static let orderPlaced = Notification.Name("orderPlaced") }

let token = center.addObserver(forName: .orderPlaced, object: nil, queue: .main) { note in
    guard let id = note.userInfo?["id"] as? String else { return }
    billing.handle(id)                          // userInfo is [AnyHashable: Any]
}

center.post(name: .orderPlaced, object: self, userInfo: ["id": id])
center.removeObserver(token)                    // the hub holds the closure until removed

